export interface UpdaterConfig {
  /** @default true */
  allowPatch?: boolean;
  /** @default false */
  autoApply?: boolean;
  /**
   * Periodic update check every `checkInterval`. `autoCheck`, `checkOnStartup` and `autoDownload`
   * are driven by the frontend: they only run once the main window has imported
   * `@tynd/plugin-updater/client` (an app that never loads that module never checks).
   * @default true
   */
  autoCheck?: boolean;
  /**
   * Download every update a check finds. Same requirement as `autoCheck`.
   * @default true
   */
  autoDownload?: boolean;
  /**
   * Default release channel (`"stable"` when unset): letters, digits, `.`, `_`, `-`, 1..64
   * characters, not starting with `.`. `updater.setChannel()` overrides it at runtime.
   * @default "stable"
   */
  channel?: string;
  /** @default "12h" */
  checkInterval?: string;
  /**
   * Run one check at startup. Same requirement as `autoCheck`.
   * @default true
   */
  checkOnStartup?: boolean;
  /**
   * Manifest URLs tried in order (fallback on network error, HTTP 5xx, 408 and 429). Each may use
   * `{{channel}}`, `{{target}}` (windows|darwin|linux), `{{arch}}` (`x86_64`|`aarch64`) and
   * `{{current_version}}`.
   */
  endpoints: [string, ...string[]];
  /** @default true */
  fallbackToFull?: boolean;
  /**
   * Fixed request headers for private update servers (e.g. `Authorization`). Values may use
   * `${env:NAME}`, expanded from the environment / `.env` files when the CLI generates the backend
   * bootstrap, so a token need not be committed. Sent only to the origins of the configured
   * endpoints (at least one endpoint needs a fixed origin), never on a cross-origin redirect.
   * Transport-owned names (`Host`, `Content-Length`, `Transfer-Encoding`, `Connection`,
   * `Proxy-Authorization`, ...) are rejected; at most 32 headers, values <= 4096 bytes.
   * Backend-only, like `proxy`. A packaged app carries the expanded value in its backend bundle:
   * use a low-privilege read token.
   */
  headers?: Record<string, string>;
  maxPatchSize?: ByteSize;
  /** @default true */
  preferPatch?: boolean;
  /** @default "modal" */
  promptStyle?: PromptStyle;
  /**
   * `http://` or `https://` proxy (`scheme://host[:port]`, no query or fragment) for updater
   * traffic. Without it the host falls back to `HTTPS_PROXY` / `ALL_PROXY`. Backend-only: never
   * injected into the renderer-visible runtime config.
   */
  proxy?: string;
  /**
   * Trusted Ed25519 public keys (base64). A signature is valid when any key verifies it, so a
   * rotation ships old + new, signs with the new key, then drops the old one.
   */
  publicKeys: [string, ...string[]];
  /** @default true */
  requireMajorPrompt?: boolean;
  /**
   * Signature checks cannot be turned off.
   * @default true
   */
  requireSignature?: true;
}

